#!/usr/bin/env node
// benny08 QA probe (adapted copy of line B's qa/pilot05/full_reference_match/benny/work/bennyprobe.mjs, read-only
// source ccr-b0757dec-dj6l1o @99ab17b): load the real game ONCE with the Screen 08 switch, goto('08') exactly like
// scripts/capture.mjs, then for each step file evaluate its JS (async function body with `R` = window.__rainbow,
// `Q` = R.qa3d()) and screenshot steps whose name ends in .shot.js. Re-renders only via Q.composer.render() (never goto
// twice in one session: the mixer phase advances).
//   node qa/match/08/benny08/work/probe08.mjs --q='match08=1' --out=DIR step1.js [step2.shot.js ...]
import { writeFileSync, readFileSync, mkdirSync } from 'node:fs';
import { basename } from 'node:path';
import { loadPlaywright, CHROMIUM_ARGS, startVite } from '../../../../../scripts/lib/pw.mjs';
const args = process.argv.slice(2);
const opt = Object.fromEntries(args.filter((a) => a.startsWith('--')).map((a) => { const [k, ...r] = a.slice(2).split('='); return [k, r.join('=')]; }));
const steps = args.filter((a) => !a.startsWith('--'));
const out = opt.out || 'qa/match/08/benny08/work/probe_out';
const stage = opt.stage || '08';
mkdirSync(out, { recursive: true });
const { chromium } = loadPlaywright();
const vite = await startVite(5241);
const browser = await chromium.launch({ args: CHROMIUM_ARGS });
const t0 = Date.now();
try {
  const page = await browser.newPage({ viewport: { width: 864, height: 1536 }, deviceScaleFactor: 1 });
  page.on('console', (m) => { if (m.type() === 'error' || m.text().startsWith('[benny')) console.log('console:', m.text()); });
  page.on('pageerror', (e) => console.log('pageerror', e.message));
  await page.goto(`${vite.url}/?qa=1&dpr=1${opt.q ? '&' + opt.q : ''}`);
  await page.waitForFunction(() => window.__rainbow?.ready === true || window.__error, null, { timeout: 240000 });
  console.log('loaded', (Date.now() - t0) / 1000);
  await page.evaluate((s) => window.__rainbow.goto(s), stage);
  await page.evaluate(() => new Promise((r) => requestAnimationFrame(() => r())));
  await page.evaluate(() => document.fonts.ready);
  await page.waitForTimeout(250);
  for (const s of steps) {
    const body = readFileSync(s, 'utf8');
    const res = await page.evaluate(async (b) => { const R = window.__rainbow, Q = R.qa3d(); const f = new Function('R', 'Q', `return (async () => { ${b} })()`); return await f(R, Q); }, body);
    if (res && res.saveAs && res.b64) { writeFileSync(`${out}/${res.saveAs}`, Buffer.from(res.b64, 'base64')); delete res.b64; }
    console.log(basename(s), JSON.stringify(res));
    if (s.endsWith('.shot.js')) {
      await page.evaluate(() => new Promise((r) => requestAnimationFrame(() => r())));
      await page.waitForTimeout(200);
      await page.screenshot({ path: `${out}/${basename(s, '.shot.js')}.png` });
    }
  }
} finally {
  await browser.close();
  await vite.close();
  console.log('done', (Date.now() - t0) / 1000);
}
"""CURRENT vs NEW Benny on Screen 08 against the APPROVED picture (benny-character-artist, 2026-11-17).
Per approved part (parts08.py masks: body fur + arm nubs, crown stripes, ribbed cuff, pom-pom, gold star):
  mean |dRGB|, share within 20 levels, luminance SSIM (mean of the 7x7 SSIM map over the part), approved vs game median
  colour, fine-detail correlation (high-pass luminance, sigma 2, inside the part eroded 3 px: Pearson r and the game's
  amplitude as a share of the approved's) - like line B's section-0 table.
  'overlap' rows: only pixels where the game shows the SAME part (UV pass ids) -> colour match without the placement error.
Regions: Benny + splash box (x 220-650, y 840-1245), Benny silhouette (approved parts), scenery (y >= 190 outside the
Benny box), whole frame (regions08.py).
usage: python3 -I compare08.py <uv.f32> LABEL=<capture.png> [LABEL2=<capture2.png> ...] [--json=OUT]"""
import sys, os, json
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import numpy as np
from PIL import Image
from scipy import ndimage as ndi
from scipy.ndimage import gaussian_filter
from parts08 import approved_parts
from geom08 import load_uv, game_ids
from regions08 import regions, ssim_map

LUMW = np.array([0.2126, 0.7152, 0.0722])
GAME_ID = dict(body=[1, 6, 7, 8, 9], crown=[2], cuff=[3], pom=[4], star=[5])


def hp(a):
    l = (a * LUMW).sum(-1)
    return l - gaussian_filter(l, 2.0)


def table(A, C, P, ids):
    d = np.abs(A - C).mean(-1); sm = ssim_map(A, C); ha, hc = hp(A), hp(C)
    out = {}
    for name, m in list(P.items()) + [('benny', np.any(np.stack(list(P.values())), 0))]:
        inner = ndi.binary_erosion(m, iterations=3)
        r = float(np.corrcoef(ha[inner], hc[inner])[0, 1]) if inner.sum() > 50 else None
        amp = float(hc[inner].std() / max(ha[inner].std(), 1e-6)) if inner.sum() > 50 else None
        row = dict(px=int(m.sum()), mean_abs=round(float(d[m].mean()), 2), within_20=round(float((d[m] <= 20).mean()), 4),
                   ssim=round(float(sm[m].mean()), 4), approved_median=np.median(A[m], 0).astype(int).tolist(),
                   game_median=np.median(C[m], 0).astype(int).tolist(),
                   detail_r=round(r, 3) if r is not None else None, detail_amp=round(amp, 3) if amp is not None else None)
        if name in GAME_ID:
"""Write the separate full-size comparison pictures + 3x Benny close-ups (no grids / collages).
usage: python3 -I pictures08.py <current_864.png> <new_864.png> [<current_1080x1920.png> <new_1080x1920.png>]
-> qa/match/08/benny08/{APPROVED_08,CURRENT_08,NEW_08}.png (864x1536, the approved picture's own size, pixel-comparable),
   {CURRENT,NEW}_08_1080x1920.png (phone-size renders), closeup_{APPROVED,CURRENT,NEW}.png (x 250-610, y 845-1225, 3x)"""
import sys, shutil
from PIL import Image
OUT = 'qa/match/08/benny08'
REF = 'references/08_final_spin_chamber.png'
BOX = (250, 845, 610, 1225)
shutil.copyfile(REF, f'{OUT}/APPROVED_08.png')  # byte copy, the reference itself is never touched
shutil.copyfile(sys.argv[1], f'{OUT}/CURRENT_08.png')
shutil.copyfile(sys.argv[2], f'{OUT}/NEW_08.png')
if len(sys.argv) > 4:
    shutil.copyfile(sys.argv[3], f'{OUT}/CURRENT_08_1080x1920.png')
    shutil.copyfile(sys.argv[4], f'{OUT}/NEW_08_1080x1920.png')
for lab, p in [('APPROVED', REF), ('CURRENT', sys.argv[1]), ('NEW', sys.argv[2])]:
    im = Image.open(p).convert('RGB').crop(BOX)
    im.resize((im.width * 3, im.height * 3), Image.LANCZOS).save(f'{OUT}/closeup_{lab}.png')
print('written')
